'use strict';
const wizardSteps=[
 {key:'sheets',name:'連接試算表',title:'步驟 1：選擇你的試算表',description:'先準備資料來源。可連接 Google Sheet，或先用 CSV 與範例試作。'},
 {key:'settings',name:'設定 Bot',title:'步驟 2：設定 Bot 基本資訊與回覆',description:'設定 Bot 資訊、AI Prompt 與 API Key，再新增關鍵詞回覆。'},
 {key:'gas',name:'測試與下載',title:'步驟 3：測試規則，下載程式',description:'基本 Bot 不需要 AI 或 RAG。先測試關鍵詞規則，再產生 GAS。'}
];
const advancedPages={models:{title:'進階選配：AI 與 API Key 測試',description:'OpenAI、Gemini、Grok 可獨立測試，無須建立 RAG。'},knowledge:{title:'進階選配：RAG 文件知識庫',description:'只有需要根據文件回答時才使用。預設關閉，不影響基本關鍵詞回覆。'}};
function wizardIndex(){return wizardSteps.findIndex(s=>s.key===(page==='test'?'gas':page))}
function renderNav(){const current=wizardIndex();document.querySelector('#navigation').innerHTML=wizardSteps.map((s,i)=>`<a href="#${s.key}" class="wizard-step ${i===current?'current':''}" ${i===current?'aria-current="step"':''}><span class="step-number">${i+1}</span><span><small>必要步驟 ${i+1}</small><strong>${s.name}</strong></span></a>`).join('');document.querySelector('#breadcrumb-page').textContent=current<0?'進階選配':`步驟 ${current+1} / 3`}
function heading(){return ''}
function render(){const i=wizardIndex(),step=i<0?advancedPages[page]:wizardSteps[i];renderNav();document.querySelector('#main').innerHTML=`<div class="wizard-heading"><span class="step-kicker">${i<0?'OPTIONAL':`STEP 0${i+1} / 03`}</span><h1>${step.title}</h1><p>${step.description}</p></div><div class="wizard-content">${wizardContent()}</div><div class="wizard-bottom"><div>${i>0?`<button class="btn" data-wizard-go="${wizardSteps[i-1].key}">← 上一步</button>`:i<0?'<button class="btn" data-wizard-go="gas">← 返回基本流程</button>':'<span class="wizard-save-note">沒有文件知識庫也能製作 LINE Bot。</span>'}</div>${i>=0&&i<2?`<button class="btn primary" data-wizard-go="${wizardSteps[i+1].key}">下一步：${wizardSteps[i+1].name} ${icon('arrow')}</button>`:'<span class="wizard-save-note">GAS 與 LINE 部署需完成帳號設定。</span>'}</div><section class="optional-links"><span>進階選配 · 需要時再開啟</span><a href="#settings">Bot／AI 連線設定</a><a href="#knowledge">RAG 文件知識庫${state.config.ragEnabled?'（開啟）':'（關閉）'}</a></section>`;if(page==='knowledge')renderFiles();if(page==='test')renderChat();restoreLiveInputs()}
function wizardContent(){if(page==='sheets')return wizardSheets();if(page==='knowledge')return `<section class="panel wizard-card section-space"><label class="setting-item"><span><strong>啟用 RAG（選配）</strong><p>未符合關鍵詞時，才搜尋文件。文件匯入不會自動啟用。</p></span><input id="rag-enabled" type="checkbox" ${state.config.ragEnabled?'checked':''}></label></section>`+wizardKnowledge();if(page==='models')return apiTestCard();if(page==='settings')return rulesPage();return wizardFinish()}
function wizardSheets(){const headers=state.sheet?.headers||['Time','userid','message','AI_Response'];const rows=state.sheet?.rows||[];return `<section class="panel wizard-card"><div class="choice-icon">${icon('sheet')}</div><h2>先下載範本，再連接試算表</h2><p>範本已準備好 Data、Setting、Keywords 三個分頁。先下載修改，再上傳 Google Drive 並另存為 Google 試算表。</p><div class="wizard-source-actions"><a class="btn primary" href="templates/linebot-template.xlsx" download="linebot範本.xlsx">${icon('download')}下載 LineBot Excel 範本</a>${button('連接 Google Sheet','connect-sheet','link')}</div><div class="info-list"><div class="info-line"><strong>Data</strong><span>Time、userid、message、AI_Response；保留你的原始欄位。</span></div><div class="info-line"><strong>Setting</strong><span>Bot 名稱、Prompt、AI 模型與選配開關，B 欄可修改。</span></div><div class="info-line"><strong>Keywords</strong><span>一列一條規則，已附文字及網址回覆範例。</span></div></div><p class="note">請保留分頁順序與欄名。API Key 填在 GAS 指令碼屬性，不填入範本。Data 目前僅提供欄位範本，訊息自動記錄仍需 LINE 入口串接。</p><div class="source-summary">${icon('sheet')}<span>${state.sheet?`已匯入：${escapeHTML(state.sheet.name)} · ${rows.length} 筆資料`:'尚未連接；GAS 預設使用 Data 範本欄位。'}</span></div>${state.config.sheetUrl?`<p class="note">${escapeHTML(runtime.sheetStatus)}</p>`:''}<details class="wizard-details"><summary>其他資料來源：匯入 CSV 與查看欄位</summary>${button('匯入 CSV 檔案','upload-sheet','upload')}<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">CSV 僅包含一個分頁。Excel 範本請先轉為 Google 試算表後連接，網頁目前不直接匯入 XLSX。</p></details></section>`}
function wizardKnowledge(){const review=state.docs.filter(d=>d.status==='review').length;return `<section class="panel"><div class="wizard-card compact"><div class="wizard-section-heading"><div><h2>你的知識文件</h2><p>已加入 ${state.docs.length} 份文件${review?`，其中 ${review} 份 OCR 文字待確認`:''}。</p></div>${button('加入文件','add-source','plus','primary')}</div><p class="wizard-inline-note">可實際匯入 TXT／Markdown。PDF OCR 和 Drive 同步目前為示範。</p><div class="file-toolbar"><div class="tabs"><button class="tab ${filter==='all'?'active':''}" data-filter="all">全部文件</button><button class="tab ${filter==='review'?'active':''}" data-filter="review">待確認 ${review}</button></div><label class="search">${icon('search')}<input id="file-search" type="search" placeholder="搜尋文件" aria-label="搜尋文件" value="${escapeHTML(query)}"></label></div></div><div id="file-list"></div><details class="wizard-details inset"><summary>進階：自動同步與 OCR 設定</summary><p class="note">${state.config.auto?'自動同步偏好：每 '+state.config.interval+' 分鐘':'自動同步偏好：關閉'} · 每日 OCR 上限 ${state.config.limit} 頁。背景服務尚未接通。</p><div class="actions">${button('修改同步設定','sync-settings','settings')}${button(syncing?'同步中…':'模擬同步','sync','refresh')}</div></details></section>`}
function wizardFinish(){return `<div class="finish-tabs"><a href="#gas" ${page==='gas'?'aria-current="page"':''}>下載程式</a><a href="#test" ${page==='test'?'aria-current="page"':''}>先測試回答</a></div>`+(page==='test'?`<div class="wizard-chat">${testPage()}</div>`:`<section class="panel wizard-card"><div class="choice-icon">${icon('code')}</div><h2>GAS 範本已依目前設定產生</h2><p>下載程式與設定表，關鍵詞規則可從 Google Sheet 載入；AI 與 RAG 預設關閉。</p><div class="wizard-source-actions">${button('下載 GAS 程式','download-gas','download','primary')}${button('下載設定表（Setting）','export-config','sheet')}${button('下載關鍵詞表','export-rules','sheet')}</div><div class="wizard-inline-note">API 與 Google 實際連線結果請看各功能的測試狀態。LINE 入口與 GAS 雲端執行仍需部署；RAG OCR 背景服務尚未完成。</div><details class="wizard-details"><summary>查看程式碼與檢查結果</summary><div class="actions">${button('檢查範本語法','check-gas','shield')}${button('複製程式','copy-gas','code')}</div><div class="code-box"><pre><code>${escapeHTML(generateGas())}</code></pre></div></details><details class="wizard-details"><summary>下載後，如何部署？</summary>${['把設定 CSV 貼入試算表第二個分頁，命名為「Setting」。','建立 Apps Script 專案，貼上下載的程式。','設定試算表 ID。只有啟用 AI／RAG 時，才需要配置對應服務。','執行設定表綁定與連線測試；LINE 驗證入口需另外配置。'].map((t,i)=>`<div class="guide-step"><b>${i+1}</b><span>${t}</span></div>`).join('')}</details></section>`)}
function persistWizardStep(){if(page==='settings'){const error=ruleError(state.rules);if(error){toast(error);return false}if(!state.config.botName.trim()||!state.config.fallback.trim()){toast('Bot 名稱與未命中回覆不可空白。');return false}}return true}
document.addEventListener('click',e=>{const control=e.target.closest('[data-wizard-go], .wizard-step, .finish-tabs a');if(!control)return;e.preventDefault();if(!persistWizardStep())return;navigate(control.dataset.wizardGo||control.getAttribute('href').slice(1));document.querySelector('#main').scrollIntoView?.({block:'start',behavior:'instant'})});
document.querySelector('#help-button').onclick=()=>openModal('3 個必要步驟，AI 與 RAG 自由選配',`<div class="info-list">${wizardSteps.map((s,i)=>`<div class="guide-step"><b>${i+1}</b><span>${s.name}</span></div>`).join('')}</div><p class="note">可以使用範例先走完流程。進階選項預設收合，API Key 與 Google Sheet 需自行輸入憑證、授權後實測；LINE 與 OCR 尚待部署。</p>`,button('了解','close-modal'));
render();
